using System.Collections.Generic;
using System.IO;
using NUnit.Framework;
using ShadowSteps.Core;
using ShadowSteps.Data;

namespace ShadowSteps.Tests.EditMode
{
    /// <summary>
    /// Shipped world-1 pack gate. Since D-026 the pack is generated by Tools/LevelSpecs/world1_v2.json (levels 1 and 4
    /// kept from the migrated reference) under the V2 detection rule. Every level must be valid, solvable, carry a fresh
    /// C# solver trace in validation_v2.json, and the measured mechanic-necessity sets below must hold so that a
    /// regeneration changes them deliberately (Docs/LEVEL_CURRICULUM.md).
    /// </summary>
    public class PackagedPackTests
    {
        [Test]
        public void Pack_IsSchema2_With20Levels_ValidAndWarningFree()
        {
            var pack = TestPaths.LoadPackagedPack();
            Assert.AreEqual(2, pack.FormatVersion);
            Assert.AreEqual(20, pack.Levels.Count);
            Assert.AreEqual(0, pack.Warnings.Count, string.Join("\n", pack.Warnings));
            var report = LevelValidator.ValidatePack(pack.Levels, new ValidationOptions { GuardOverlapIsErrorForLegacy = true });
            Assert.IsTrue(report.IsValid, report.ToString());
            Assert.AreEqual(0, report.WarningCount, report.ToString());
            for (int i = 0; i < 20; i++) Assert.AreEqual(i + 1, pack.Levels[i].Id, "catalog order");
            foreach (var l in pack.Levels) Assert.AreEqual(DetectionRule.BeforeOrAfterGuardMove, l.Detection, "level " + l.Id);
        }

        [Test]
        public void Levels1And4_AreTheMigratedReferenceLevels()
        {
            var reference = TestPaths.LoadPack();
            foreach (int id in new[] { 1, 4 })
            {
                var r = reference.FindById(id);
                var p = TestPaths.LoadPackagedPack().FindById(id);
                Assert.AreEqual(r.Name, p.Name);
                CollectionAssert.AreEqual(r.Walls, p.Walls);
                Assert.AreEqual(r.Graph.EdgeCount, p.Graph.EdgeCount);
                Assert.AreEqual(r.Guards.Count, p.Guards.Count);
                for (int g = 0; g < r.Guards.Count; g++) CollectionAssert.AreEqual(r.Guards[g].Route, p.Guards[g].Route);
            }
        }

        [Test]
        public void ValidationV2_ReplaysToWins_AndMatchesCurrentSolver()
        {
            var pack = TestPaths.LoadPackagedPack();
            var entries = JsonAccess.AsArray(MiniJson.Parse(File.ReadAllText(TestPaths.PackagedValidationPath)), "validation_v2");
            Assert.AreEqual(20, entries.Count);
            foreach (JsonObject e in entries)
            {
                int id = JsonAccess.AsInt(e["level"], "level");
                var level = pack.FindById(id);
                Assert.GreaterOrEqual(JsonAccess.AsInt(e["moves"], "moves"), 1, "level " + id + " must be solvable under the V2 rule");
                var tokens = new List<string>();
                foreach (var t in (List<object>)e["actions"]) tokens.Add((string)t);
                var actions = GameActionUtil.ParseSequence(tokens);
                var replay = GameSession.Replay(level, actions);
                Assert.IsTrue(replay.Won, "level " + id + "\n" + replay.Trace());
                Assert.AreEqual(JsonAccess.AsInt(e["moves"], "moves"), replay.ValidTurns, "moves for level " + id);
                var solved = Solver.Solve(level);
                Assert.AreEqual(GameActionUtil.ToTokenString(actions), solved.ActionTokens, "solver path drifted for level " + id);
                Assert.AreEqual(JsonAccess.AsInt(e["states_checked"], "states_checked"), solved.StatesExplored, "explored states for level " + id);
                Assert.AreEqual(JsonAccess.AsBool(e["key_required"], "key_required"), LevelMetricsAnalyzer.Analyze(level).KeyRequired, "key requirement for level " + id);
            }
        }

        [Test]
        public void Curriculum_ShortestSolutionsRiseAcrossTiers()
        {
            // Measured pars per tier (Docs/LEVEL_CURRICULUM.md). Individual levels may dip; tier averages must rise.
            var par = new Dictionary<int, int>();
            foreach (JsonObject e in JsonAccess.AsArray(MiniJson.Parse(File.ReadAllText(TestPaths.PackagedValidationPath)), "v"))
                par[JsonAccess.AsInt(e["level"], "level")] = JsonAccess.AsInt(e["moves"], "moves");
            double Avg(int from, int to) { double s = 0; for (int i = from; i <= to; i++) s += par[i]; return s / (to - from + 1); }
            Assert.Less(Avg(1, 4), Avg(5, 8), "easy -> easy/medium");
            Assert.Less(Avg(5, 8), Avg(9, 12), "easy/medium -> medium");
            Assert.Less(Avg(9, 12), Avg(13, 16), "medium -> medium/hard");
            Assert.Less(Avg(13, 16), Avg(17, 20), "medium/hard -> hard");
            for (int i = 1; i <= 20; i++) Assert.IsTrue(par[i] >= 6 && par[i] <= 28, "level " + i + " par " + par[i] + " outside the design bands");
        }

        [Test]
        public void MechanicNecessity_IsMeasuredUnderV2Detection()
        {
            // Constrained solves on the shipped pack (regenerate with Tools/generate_levels.sh and update deliberately).
            var expectedWait = new HashSet<int> { 2, 3, 6, 7, 8, 10, 12, 15, 16, 17, 18 };
            var expectedSmoke = new HashSet<int> { 11, 14, 16, 19, 20 };
            var expectedEmp = new HashSet<int>();
            var expectedKey = new HashSet<int> { 9, 10, 13, 16, 19, 20 };
            var wait = new HashSet<int>(); var smoke = new HashSet<int>(); var emp = new HashSet<int>(); var key = new HashSet<int>();
            foreach (var level in TestPaths.LoadPackagedPack().Levels)
            {
                var m = LevelMetricsAnalyzer.Analyze(level);
                Assert.IsTrue(m.ShortestWinTurns > 0, "level " + level.Id + " unsolvable: " + m);
                Assert.IsTrue(m.ShortestSolutionCount <= 20, "level " + level.Id + " is too loose: " + m);
                if (m.WaitRequired) wait.Add(level.Id);
                if (m.SmokeRequired) smoke.Add(level.Id);
                if (m.EmpRequired) emp.Add(level.Id);
                if (m.KeyRequired) key.Add(level.Id);
            }
            CollectionAssert.AreEquivalent(expectedWait, wait, "WAIT required");
            CollectionAssert.AreEquivalent(expectedSmoke, smoke, "smoke required");
            CollectionAssert.AreEquivalent(expectedEmp, emp, "EMP required (EMP is a no-op for the player, KNOWN_ISSUES #19)");
            CollectionAssert.AreEquivalent(expectedKey, key, "key required");
        }

        [Test]
        public void GadgetCharges_FollowTheCurriculum()
        {
            var pack = TestPaths.LoadPackagedPack();
            foreach (var l in pack.Levels)
            {
                bool smokeLevel = new HashSet<int> { 11, 14, 16, 19, 20 }.Contains(l.Id);
                bool empLevel = new HashSet<int> { 12, 15, 20 }.Contains(l.Id);
                Assert.AreEqual(smokeLevel ? 1 : 0, l.SmokeCharges, "smoke charges of level " + l.Id);
                Assert.AreEqual(empLevel ? 1 : 0, l.EmpCharges, "EMP charges of level " + l.Id);
                Assert.AreEqual(new HashSet<int> { 9, 10, 13, 16, 19, 20 }.Contains(l.Id), l.HasKey, "key on level " + l.Id);
            }
        }
    }
}
